#!/usr/bin/env python3
"""Repair and package all nine Torah 17 Parparos records against their Hebrew."""
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'public/reader/parparos-lechochma/section-18.json'; OUT=ROOT/'public/reader/super/likutay-moharan/1/17/parparos-lechochma.json'
SOURCE_INDICES=[3,5,7,9,11,13,15,17,19]
# Faithful same-record English synopses replace the visibly shifted/duplicated legacy fields.
REPAIRED=[
"Letter א. Torah 17 was delivered on Shabbat Chanukah 5566 (1805), a year in which many converts were made after finding in their own books teachings contrary to their former faith. The discourse explains how this can happen.",
"On the teaching ‘it was found written what Mordechai had reported’: Mordechai represents rejection of idolatry. The true tzaddik reveals God's pride in every Jew—even the least Jew who still bears the name Israel—and also in converts. A captive spark from Israel may forget its holy source and become attached to idolatry, yet because its root is good it is not wholly severed from God. Its return is the realization that God's sovereignty is sufficient and no other worship is needed; idolatry lives only from captive sparks of holiness.",
"Letter ב. The captive good falls by forgetting that it belongs to the souls of Israel, who arose first in God's thought and for whose glory creation was made. Even when exile prevents mitzvot, a Jew should know that God still takes pride in his holy faith. Charity creates calm, pure air in which the tzaddik's anti-idolatry words travel and are written even in the nations’ books. The captive good then remembers its source, tears itself free, draws some evil out with it as converts, repairs the altar and intellect, and enables the tzaddik's light to be seen.",
"Letter ג. When the captive good remembers its stature through the tzaddik's discovery of God's pride in every Jew, great fear awakens: it recognizes that it is a tiny sea-creature approaching the Leviathan's mouth and possible destruction. Love also awakens, symbolized by the sea-goat's horn, and gives it strength to return. The fullest revelation of awe comes especially from the tzaddik's search for God's pride in ordinary and fallen Jews, not only in the few obvious tzaddikim; from fear and love the converts emerge and the tzaddik's light is revealed.",
"Letter ד, on the teaching that folly and the husks draw from the altar. Creation's mineral, vegetable, animal and human levels reach their purpose through a person who eats to gain strength for serving God; God's pride in Israel is the root of creation's particular wills. Holy eating elevates the divine vitality in food and sends its waste outward, while gluttonous eating strengthens folly and clouds the intellect. Thus proper eating repairs the altar and reveals wisdom; damaged eating lets the husk seize the sparks of mind.",
"Letter ה. Eating by Israel clarifies and raises holy sparks: divine vitality leaves the food's physical shell, joins the person's strength for serving God, and reveals God's glory, while refuse falls away. Shell and fruit, outer and inner, repeat at every level—food, body, humanity, Israel and each individual. These distinctions preserve free choice; eating in holiness gives the shell only its necessary life and raises wisdom, whereas indulgence empowers folly and can turn knowledge toward evil.",
"Letter ו. Shell and fruit recur throughout all levels, with what is inner on one level becoming outer relative to a higher one. The food's vitality passes through liver, heart and brain; humanity is inner relative to lower creation, Israel is inner relative to the nations, and each Jew also has outer and inner aspects. Darkness and folly exist so light and wisdom can be revealed through free choice. When eating is holy, wisdom extracts its sparks; when eating is corrupted, folly captures the mind and conceals the tzaddik's light.",
"Letter ז. Converts complete the damaged altar. When folly and the husks overpower holy sparks and parts of Israel's souls, proper clarification reverses the process: the good escapes and pulls part of the nations’ evil with it, producing converts. This parallels holy eating, which extracts sparks from the food's shell. Because eating belongs to the world of action, corrupt eating clouds deeds and mind and feeds idolatry; sacred eating and conversion repair the altar and restore the intellect.",
"Letters ח–ט. The final repair of intellect depends on vessels of action, especially charity: ‘the work of charity shall be peace.’ Charity multiplies friends and makes the air calm and pure, so the tzaddik's words can travel into the nations’ books, awaken converts, complete the altar and perfect the mind. Though the world of action receives from higher worlds, it was first in God's purpose because creation is for Israel within action. Likewise, although the poor person receives, the giver receives the deeper benefit: charity repairs action, reveals God's pride, and lets the light of the true tzaddik be seen."
]
def main():
 data=json.loads(SOURCE.read_text(encoding='utf-8-sig').replace('\x00','')); segments=data.get('segments',[])
 if len(segments)!=9 or [int(x['index']) for x in segments]!=SOURCE_INDICES: raise RuntimeError('Frozen Parparos section 18 indices changed')
 packaged=[]
 for index,(source,en) in enumerate(zip(segments,REPAIRED),1):
  he=str(source.get('he') or '').strip()
  if not he or not en or 'Siman 16' in en or 'Translator\'s Summary' in en: raise RuntimeError(f'Unverified Parparos record {index}')
  packaged.append({**source,'index':index,'sourceIndex':int(source['index']),'sourceSection':18,'sourceEnglish':source.get('en',''),'en':en,'translationRepair':'English replaced after same-record Hebrew verification; legacy field was shifted, duplicated, mislabeled, or summary-drifted.'})
 out={**data,'id':'plc-17-super','torah':17,'displayNumber':17,'sourceSection':18,'sourceId':data.get('id'),'segments':packaged,'totalParagraphs':9,'totalSegments':9,'hasEnglish':True,'sourceFile':str(SOURCE.relative_to(ROOT)),'superReaderMetadataRepair':'Normalized source odd indices 3–19 to 1–9, retained original indices/section, and replaced every shifted English field with a verified same-record English synopsis.'}
 OUT.parent.mkdir(parents=True,exist_ok=True); OUT.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print('Repaired Parparos Torah 17: 9 bilingual same-record synopses, normalized 1–9; preserved source indices 3–19 and section 18.')
if __name__=='__main__': main()
